-- ---author:liusq---date:20260827-----for:LHZP-1985 【chat2bi】AI聊天 生成图表 添加条件 默认查询条数
ALTER TABLE `chat2bi_domain` ADD COLUMN `aggregate_query_limit` int NULL DEFAULT 50 COMMENT '聚合查询默认返回条数上限';
ALTER TABLE `chat2bi_domain` ADD COLUMN `detail_query_limit` int NULL DEFAULT 50 COMMENT '明细查询默认返回条数上限';

-- author:scott---date:20260911--for:【安全修复 GHSA-8cj9-3528-wp9p】新增「标准权限」隐藏菜单及 system:user:select 选人查询权限。该权限不默认授权，由管理员在角色授权界面按需勾选后方可查询用户列表 ---
SELECT '2098348026237030401', '', '标准权限', NULL, NULL, 0, NULL, NULL, 0, NULL, '1', 999, 0, NULL, 1, 0, 1, 0, '系统标准权限集合（隐藏菜单，仅用于角色授权）', 'admin', '2026-09-11 00:00:00', NULL, NULL, 0, 0, '1', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `sys_permission` WHERE `id` = '2098348026237030401');
SELECT '2098348026237030402', '2098348026237030401', '用户选择查询', NULL, NULL, 0, NULL, NULL, 2, 'system:user:select', '1', NULL, 0, NULL, 1, 0, 0, 0, '选人组件、通讯录等场景查询用户列表所需权限', 'admin', '2026-09-11 00:00:00', NULL, NULL, 0, 0, '1', 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `sys_permission` WHERE `id` = '2098348026237030402');

-- update-begin--author:scott---date:20261012---for:【issues/9820】租户套餐包菜单支持分配数据规则
ALTER TABLE `sys_tenant_pack_perms` ADD COLUMN `data_rule_ids` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '数据权限ids' AFTER `permission_id`;

-- update-begin--author:scott---date:20261014---for:【GHSA-qv87-c4w6-699m/GHSA-5jhm-3x8j-wwhr】OpenAPI授权管理内置的演示AK/SK随发布包公开，清空其SK（代码已拒绝空SK）并标记为测试数据，需在授权管理重新生成AK/SK后才能调用；仅处理SK仍为出厂值的记录，已重新生成的不受影响
UPDATE `open_api_auth`
   SET `sk` = '',
       `name` = '【测试数据】请重新生成AK/SK后使用'
 WHERE `id` = '1922164194775056386'
   AND `sk` IN ('4hV5dBrZtmGAtPdbA5yseaeKRYNpzGsS', 'XpZpRzlwVBBrEiyIwS5FdRQPGQZsMxJw');

-- author:scott---date:20261015--for:【安全修复 GHSA-8cj9-3528-wp9p】修正「标准权限」隐藏菜单配置：1) is_leaf 误设为1，角色授权树不展开下级，无法勾选「用户选择查询(system:user:select)」；2) 一级菜单缺少 url/component，授权后下发到前端路由 path 为空导致白屏，补齐路由字段并设为不生成路由(is_route=0) ---
UPDATE `sys_permission`
   SET `is_leaf` = 0,
       `url` = '/standardPermission',
       `component` = 'layouts/default/index',
       `is_route` = 0
 WHERE `id` = '2098348026237030401';

