-- 微服务网关：jeecg-system 路由补充 /jimu/**（积木 ChatBI 页面 /jimu/chat2bi/index 经网关转发 404）
UPDATE `sys_gateway_route` SET `predicates` = REPLACE(`predicates`, '"/openapi/**"]', '"/openapi/**","/jimu/**"]')
WHERE `router_id` = 'jeecg-system' AND `predicates` NOT LIKE '%/jimu/**%';

